<script lang="ts">
 import {createEventDispatcher} from 'svelte';import type {Workflow} from './automations-client';import './automations.css';
 export let workflow:Workflow;export let busy=false;export let receiptId='';
 const dispatch=createEventDispatcher<{run:{workflow:Workflow;label:string;key:string}}>();let open=false,label='Internal approval check',request:{label:string;key:string}|null=null,seen='',baseline='';
 $: if(seen!==workflow.id){seen=workflow.id;open=false;request=null;label='Internal approval check';}
 function submit(){if(!workflow.actions.canRun||workflow.intent!=='internal_approval_test'||busy||!label.trim())return;if(!request){baseline=receiptId;request={label:label.trim(),key:crypto.randomUUID()};}dispatch('run',{workflow,label:request.label,key:request.key});}
</script>
{#if workflow.intent==='internal_approval_test'&&workflow.actions.canRun}<section class="starli-automations internal-run" aria-label="Run internal approval test"><h3>Internal approval test</h3><p class="sa-muted">Run this internal workflow and request its exact human approval. It records a Starli test receipt and performs no external business action.</p>{#if receiptId&&request&&receiptId!==baseline}<p class="sa-muted" role="status">Internal test submitted. Its approval and result stay in the original conversation.</p><small class="sa-reference">Execution {receiptId}</small><button on:click={()=>{request=null;open=true;}}>Start another internal test</button>{:else if open}<form on:submit|preventDefault={submit}><label class="sa-label">Test label<input class="sa-input" bind:value={label} disabled={busy||!!request} maxlength="160" required/></label>{#if request}<p class="sa-muted">If the result is interrupted, check the conversation first. Submitting again checks this same internal request.</p>{/if}<button class="sa-primary" disabled={busy||!label.trim()}>{busy?'Submitting…':request?'Check same request':'Run internal test'}</button></form>{:else}<button class="sa-primary" disabled={busy} on:click={()=>open=true}>Run internal test</button>{/if}</section>{/if}
<style>.internal-run{border:1px solid #e6ebf4;border-radius:10px;background:white;padding:18px;margin:16px 0}.internal-run button{margin-top:12px}.internal-run .sa-input{max-width:450px}@media(max-width:500px){.internal-run{padding:15px}}</style>
